// Enumerate all C(21,5) subsets, independent of the old degree-bucket and embedding routines.
use std::io::{self,BufRead};fn main(){for line in io::stdin().lock().lines(){let l=line.unwrap();let(id,s)=l.split_once(' ').unwrap();let b=s.as_bytes();assert_eq!(b[0],84);let mut a=[0u32;21];let mut k=0;for j in 0..21{for i in 0..j{if (b[1+k/6]-63)&(32>>(k%6))!=0{a[i]|=1<<j;a[j]|=1<<i}k+=1}}let mut cnt=[0usize;1024];for i in 0..17{for j in i+1..18{for k in j+1..19{for h in k+1..20{for m in h+1..21{let v=[i,j,k,h,m];let mask=(1<<i)|(1<<j)|(1<<k)|(1<<h)|(1<<m);if v.iter().any(|&x|(a[x]&!mask).count_ones()!=4){continue}let mut code=0;for y in 1..5{for x in 0..y{code|=((a[v[x]]>>v[y])&1)<<(y*(y-1)/2+x)}}cnt[code as usize]+=1}}}}}print!("{}",id);for(i,n)in cnt.iter().enumerate(){if *n>0{print!(" {}:{}",i,n)}}println!()}}
